	"testing"

	"github.com/stretchr/testify/require"
)

func TestHTML(t *testing.T) {
	t.Run("f", func(t *testing.T) {
		t.Run("empty select clause", func(t *testing.T) {
			t.Run("no error", func(t *testing.T) {
				f()
			})
		})
	})

	t.Run("g", func(t *testing.T) {
		t.Run("no error", func(t *testing.T) {
			g()
		})
	})
}

